@rule("s10", "s3", otherwise="NotMentioned")
def reverse_engineering():
    return "Contradiction" if "reverse engineer" in name else "NotMentioned"

query = agreement_acceptance() if agreement_acceptance() != "NotMentioned" else reverse_engineering()
